-- Migration: Year 2 - Hematology Pathology MCQs Part 8 (266-300)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Hematology Pathology', 'hematology-pathology', 3, 2, 61)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- THROMBOPHILIA (266-278)
    (v_topic_id, 'Factor V Leiden is the most common inherited thrombophilia. What is the mechanism?', '["Factor V is overproduced due to gene duplication", "A point mutation (Arg506Gln) makes Factor Va resistant to inactivation by Activated Protein C (APC), causing persistent procoagulant activity", "Factor V binds fibrinogen more tightly", "Factor V activates more thrombin than normal"]', 1, 'Normal Protein C (activated by thrombomodulin-thrombin complex) cleaves and inactivates Factors Va and VIIIa. Factor V Leiden has a mutated APC cleavage site. APC cannot inactivate mutant FVa, leading to prolonged procoagulant activity and hypercoagulability. Most common in Caucasians (~5% prevalence).'),
    (v_topic_id, 'Prothrombin G20210A mutation causes thrombophilia by what mechanism?', '["It activates prothrombin constitutively", "A gain-of-function mutation in the 3-prime UTR of prothrombin mRNA increases prothrombin translation, raising plasma prothrombin (Factor II) levels by ~30%", "It makes prothrombin resistant to antithrombin", "It prevents prothrombin cleavage by thrombin"]', 1, 'Prothrombin G20210A: single nucleotide change in the 3-prime untranslated region of the prothrombin gene increases mRNA stability and translational efficiency → elevated plasma prothrombin → more thrombin generated → hypercoagulability. Second most common inherited thrombophilia after Factor V Leiden.'),
    (v_topic_id, 'Protein C deficiency causes thrombophilia. What does Protein C normally do?', '["Activates Factor X to Xa", "Protein C (activated by the thrombomodulin-thrombin complex on endothelial cells) inactivates Factors Va and VIIIa, limiting clot propagation", "Inhibits thrombin directly (like antithrombin)", "Cleaves fibrinogen to fibrin"]', 1, 'Protein C is a vitamin K-dependent anticoagulant. Thrombin bound to thrombomodulin activates Protein C. Activated PC + Protein S (cofactor) cleave Factors Va and VIIIa, dampening the coagulation cascade. Deficiency → uncontrolled coagulation → venous thromboembolism.'),
    (v_topic_id, 'Warfarin-induced skin necrosis is a paradoxical complication most common in patients with?', '["Factor V Leiden heterozygosity", "Protein C or Protein S deficiency — warfarin first depletes short-lived Protein C (t1/2 = 6 hours) before depleting pro-coagulant factors, transiently creating a hypercoagulable state causing skin microvascular thrombosis", "Antithrombin deficiency", "Prothrombin G20210A"]', 1, 'Warfarin inhibits vitamin K-dependent factors (II, VII, IX, X, Protein C, S). Protein C has the shortest half-life. Early in warfarin therapy, Protein C drops first → brief hypercoagulable state → skin necrosis (thrombosis of dermal microvasculature). Prevention: bridge with heparin when starting warfarin.'),
    (v_topic_id, 'Antithrombin (AT) deficiency causes thrombophilia. What does antithrombin normally do?', '["Activates fibrinolysis via tPA", "Inhibits thrombin and Factors IXa, Xa, XIa, XIIa by forming irreversible complexes (serpin); activity is greatly enhanced by heparin (1000-fold)", "Activates Protein C", "Degrades fibrin clots"]', 1, 'Antithrombin is a serine protease inhibitor (SERPIN) that neutralizes multiple coagulation serine proteases, primarily thrombin and Factor Xa. Heparin binds AT and causes a conformational change that accelerates AT inhibition 1000-fold. AT deficiency: heparin may be less effective (requires higher doses).'),
    (v_topic_id, 'Antiphospholipid Syndrome (APS) is an acquired thrombophilia. Which antibodies define it?', '["Anti-dsDNA and anti-Smith antibodies", "Antiphospholipid antibodies: lupus anticoagulant, anti-cardiolipin IgG/IgM, and anti-beta2-glycoprotein I antibodies — causing arterial and venous thrombosis and pregnancy loss", "Anti-platelet GPIb antibodies", "Anti-ADAMTS13 antibodies"]', 1, 'APS criteria: clinical (venous/arterial thrombosis OR pregnancy morbidity: recurrent miscarriage, fetal death, preeclampsia) + lab (lupus anticoagulant OR anti-cardiolipin OR anti-B2GPI — positive on 2 occasions >12 weeks apart). Major associations: SLE, other autoimmune diseases, or primary APS.'),
    (v_topic_id, 'The lupus anticoagulant paradoxically PROLONGS the aPTT in vitro but causes THROMBOSIS in vivo. Why?', '["In vitro: antibodies consume phospholipids needed as the aPTT assay surface, prolonging the test. In vivo: antibodies bind phospholipids on platelets and endothelium, activating procoagulant pathways", "Lupus anticoagulant directly inhibits Protein C", "In vitro and in vivo effects are the same — it prolongs clotting in both", "Lupus anticoagulant activates fibrinolysis in vivo"]', 0, 'The aPTT assay uses phospholipids as the reaction surface. Lupus anticoagulant antibodies bind these phospholipids, reducing the reaction surface and prolonging the aPTT in vitro. In vivo, anti-phospholipid antibodies activate platelet/endothelial phospholipids and inhibit natural anticoagulants, causing thrombosis.'),
    (v_topic_id, 'Which clinical manifestation is the hallmark of Antiphospholipid Syndrome in pregnant women?', '["Placenta previa", "Recurrent pregnancy loss — particularly second-trimester fetal loss from placental thrombosis and infarction", "Gestational diabetes", "Polyhydramnios"]', 1, 'APS causes placental thrombosis and infarction, resulting in: recurrent spontaneous miscarriages (1st trimester from decidual thrombosis), fetal death (2nd/3rd trimester from placental infarction), severe preeclampsia, and intrauterine growth restriction (IUGR). Treatment: low-dose aspirin + LMWH throughout pregnancy.'),
    (v_topic_id, 'Which combination of test results suggests a mixing study pattern of an INHIBITOR rather than a factor deficiency?', '["Prolonged aPTT corrects immediately upon mixing with normal plasma", "Prolonged aPTT does NOT correct (or partially corrects) when mixed 1:1 with normal plasma, because the inhibitor present in patient plasma also inhibits factors in the normal plasma", "PT corrects with mixing", "Normal aPTT that prolongs after mixing"]', 1, 'Mixing study: patient plasma + normal plasma (1:1). Factor deficiency: normal plasma provides the missing factor → aPTT corrects. Inhibitor (antibody): antibody from patient plasma neutralizes factors in normal plasma too → aPTT remains prolonged. Incubation at 37C for 1-2 hours increases inhibitor detection sensitivity.'),
    (v_topic_id, 'Homocystinuria (classic, from CBS deficiency) causes both arterial and venous thrombosis in children. What is the mechanism of thrombosis?', '["Homocysteine activates Factor V Leiden", "Elevated homocysteine damages endothelium, promotes platelet activation, inhibits Protein C activation, and increases tissue factor expression — creating a prothrombotic state", "Homocysteine causes cryoglobulinemia", "Homocysteine acts as a procoagulant cofactor for thrombin"]', 1, 'Homocysteine is directly toxic to endothelial cells (oxidative damage), promotes smooth muscle proliferation, activates platelets, and inhibits antithrombotic mechanisms. Premature atherosclerosis + thromboembolism in young patients is classic. Also: ectopia lentis (lens dislocation), intellectual disability, Marfanoid habitus.'),
    (v_topic_id, 'Virchow Triad describes the three factors predisposing to venous thrombosis. What are they?', '["Pain, swelling, redness", "Stasis (slow blood flow), Hypercoagulability, and Endothelial injury/dysfunction", "Thrombocytopenia, coagulation factor deficiency, fibrinolytic excess", "Infection, inflammation, immune activation"]', 1, 'Virchow Triad: (1) Stasis — immobility, venous obstruction, heart failure; (2) Hypercoagulability — inherited thrombophilias, malignancy, pregnancy, OCP; (3) Endothelial injury — surgery, trauma, catheter. DVT/PE results from interaction of these three factors. Any two elements markedly increase risk.'),
    (v_topic_id, 'What is the most common inherited cause of arterial thrombosis (compared to venous thrombosis)?', '["Factor V Leiden (causes mainly venous thrombosis)", "Elevated Lipoprotein(a) and hyperhomocysteinemia are the strongest inherited risk factors for arterial thrombosis (MI, stroke); Factor V Leiden and Prothrombin mutation mainly cause venous thrombosis", "Protein C deficiency (causes arterial > venous)", "Antithrombin deficiency (causes arterial thrombosis primarily)"]', 1, 'Inherited thrombophilias predominantly cause VENOUS thrombosis (DVT, PE, cerebral sinus thrombosis, Budd-Chiari). Arterial thrombosis is mainly driven by platelet activation + atherosclerosis. Antiphospholipid syndrome is the exception — causes BOTH arterial and venous thrombosis.'),
    (v_topic_id, 'Which coagulation lab pattern is seen with Vitamin K deficiency?', '["Isolated prolonged aPTT, normal PT", "Prolonged PT first (Factor VII has the shortest half-life among VK-dependent factors), then prolonged aPTT as deficiency worsens", "Normal PT and aPTT, low platelets", "Isolated prolonged thrombin time"]', 1, 'Vitamin K is required for gamma-carboxylation of Factors II, VII, IX, X, Protein C and S. Factor VII (extrinsic pathway) has the shortest half-life (~6 hours) → PT prolongs first. Factors IX, X, II (longer half-lives) fall later → aPTT prolongs. PT/INR is the most sensitive test for VK status and liver synthetic function.'),

    -- COAGULATION LAB INTERPRETATION (279-285)
    (v_topic_id, 'A patient has isolated prolonged aPTT with no bleeding history. Mixing study corrects. Factor VIII, IX, XI levels are normal. Which factor deficiency should be considered?', '["Factor VII deficiency", "Factor XII (Hageman Factor) deficiency — prolongs aPTT (contact activation pathway) but causes NO bleeding because FXII is NOT required for in vivo hemostasis", "Factor XIII deficiency", "von Willebrand Disease"]', 1, 'Factor XII deficiency prolongs aPTT (in vitro contact activation) but does NOT cause clinical bleeding — paradoxically, FXII deficiency may actually increase thrombotic risk. Classic exam scenario: incidentally discovered aPTT prolongation in an asymptomatic patient, normal mixing study correction, and no bleeding.'),
    (v_topic_id, 'A patient has an isolated prolonged PT with normal aPTT, normal platelets, and normal bleeding time. Which factor deficiency explains this?', '["Factor IX deficiency (intrinsic pathway)", "Factor VII deficiency — FVII is the only coagulation factor exclusively in the extrinsic pathway (tissue factor pathway), so its deficiency prolongs PT only", "Factor VIII deficiency", "Factor XII deficiency"]', 1, 'PT measures the extrinsic pathway (FVII + TF → Xa → common pathway). aPTT measures the intrinsic pathway (XII, XI, IX, VIII → Xa → common pathway). Isolated PT prolongation with normal aPTT = FVII deficiency or early Vitamin K deficiency. Both PT and aPTT prolonged = common pathway (FX, FV, FII, fibrinogen) or VK deficiency/warfarin.'),
    (v_topic_id, 'The thrombin time (TT) is prolonged in which conditions?', '["Factor VII deficiency", "Heparin therapy, dysfibrinogenemia, hypofibrinogenemia, and direct thrombin inhibitors (argatroban, dabigatran) — TT measures conversion of fibrinogen to fibrin by thrombin", "Factor XII deficiency", "Vitamin K deficiency only"]', 1, 'TT: thrombin is added to patient plasma; time to fibrin clot formation is measured. It is prolonged when: (1) fibrinogen is low or abnormal (dysfibrinogenemia); (2) heparin inhibits thrombin; (3) direct thrombin inhibitors (argatroban, dabigatran) block thrombin; (4) fibrin/fibrinogen degradation products (FDPs) inhibit fibrin polymerization (as in DIC).'),
    (v_topic_id, 'D-dimer is a fibrin degradation product. What does an elevated D-dimer indicate?', '["Active fibrin clot formation and simultaneous plasmin-mediated fibrinolysis", "Platelet destruction only", "Factor deficiency", "Vitamin K deficiency"]', 0, 'D-dimers are generated when crosslinked fibrin (made by FXIII) is cleaved by plasmin. Elevated D-dimer = active clotting + fibrinolysis. High sensitivity (~95%) for DVT/PE but low specificity (elevated in surgery, pregnancy, infection, cancer, DIC). Used as a RULE-OUT test for PE/DVT when pre-test probability is low.'),

    -- TRANSFUSION MEDICINE (286-295)
    (v_topic_id, 'ABO blood group antigens are the most important in transfusion medicine. Which blood type is the universal donor for packed RBCs?', '["AB positive", "O negative — lacks A, B antigens (no rejection by anti-A or anti-B antibodies) and lacks Rh antigen (safe for Rh-negative recipients)", "O positive", "AB negative"]', 1, 'Group O- RBCs can be given to any ABO/Rh type without compatibility reaction. Used in emergency (uncrossmatched). For plasma, AB is universal donor (no anti-A or anti-B antibodies). For platelets, ABO compatibility is preferred but not as critical.'),
    (v_topic_id, 'What is the most common cause of fatal acute hemolytic transfusion reaction?', '["ABO-incompatible blood given due to clerical error (wrong patient, wrong unit, wrong label)", "Febrile non-hemolytic reaction", "Transfusion-associated GVHD", "Delayed hemolytic reaction"]', 0, 'ABO incompatibility (type O patient gets type A blood, for example) causes immediate intravascular hemolysis via complement activation. Anti-A or anti-B IgM activates complement cascade to MAC formation, lysing transfused RBCs. DIC, renal failure, and cardiovascular collapse can follow. Most cases are due to human error (mislabeling/misidentification).'),
    (v_topic_id, 'A febrile non-hemolytic transfusion reaction (FNHTR) presents as fever and chills during transfusion without hemolysis. What is the mechanism?', '["ABO incompatibility causing complement activation", "Recipient antibodies react against donor WBC antigens (HLA) in the blood product, or cytokines released from stored blood product WBCs, causing fever without RBC destruction", "Bacterial contamination of the blood product", "Iron overload from chronic transfusions"]', 1, 'FNHTR is the most common transfusion reaction. Two mechanisms: (1) recipient anti-HLA or anti-granulocyte antibodies react with donor WBCs → fever/chills; (2) cytokines (IL-1, IL-6, TNF) accumulate in stored platelet/RBC products → fever on infusion. Prevented by leukoreduction (filtering WBCs from blood products).'),
    (v_topic_id, 'Transfusion-Related Acute Lung Injury (TRALI) is the leading cause of transfusion-related mortality. What is the mechanism?', '["Iron overload causing lung fibrosis", "Donor antibodies (anti-HLA or anti-neutrophil) activate recipient pulmonary neutrophils, causing acute noncardiogenic pulmonary edema (ARDS pattern) within 6 hours of transfusion", "ABO incompatibility causing pulmonary hemorrhage", "Circulatory overload from too much volume"]', 1, 'TRALI: donor plasma contains anti-HLA Class I/II or anti-HNA antibodies that activate recipient neutrophils sequestered in lung capillaries. Activated neutrophils damage pulmonary endothelium → capillary leak → ARDS-like picture (hypoxia, bilateral infiltrates, non-cardiogenic). Onset within 6 hours. Treatment: supportive (O2, ventilation). Prevention: use male donor plasma or screened female donors.'),
    (v_topic_id, 'Transfusion-Associated Circulatory Overload (TACO) is distinguished from TRALI by?', '["TACO is non-cardiogenic; TRALI is cardiogenic pulmonary edema", "TACO is cardiogenic pulmonary edema from volume overload (high BNP, hydrostatic edema); TRALI is non-cardiogenic (normal wedge pressure, inflammatory etiology)", "TACO occurs only with platelets; TRALI occurs only with RBCs", "TACO has fever; TRALI does not"]', 1, 'TACO vs TRALI: both cause acute respiratory distress during/after transfusion. TACO: cardiogenic (elevated BNP/proBNP, elevated CVP, responds to diuretics). TRALI: non-cardiogenic (normal filling pressures, inflammatory, no diuretic response). TACO is more common and underrecognized, especially in elderly patients with cardiac disease.'),
    (v_topic_id, 'Delayed hemolytic transfusion reaction occurs 3-14 days post-transfusion. What is the mechanism?', '["ABO incompatibility causing acute complement activation", "Anamnestic (secondary) immune response: recipient has low-level alloantibodies (from prior transfusion/pregnancy) against minor RBC antigens (Kidd, Duffy, Kell) that are undetectable before transfusion but rapidly amplify upon re-exposure", "Donor RBC senescence after 3 days", "Iron overload from transfusion"]', 1, 'Delayed hemolytic reaction: prior sensitization (past transfusion or pregnancy) creates memory B-cells against minor blood group antigens. At time of transfusion, antibody titers are too low to detect. Upon re-exposure, rapid antibody boost (anamnestic response) → extravascular hemolysis of transfused cells 3-14 days later. Labs: falling Hgb, positive DAT, new alloantibody on screen.'),
    (v_topic_id, 'Massive transfusion (>10 units PRBCs in 24 hours) causes which metabolic complication?', '["Hyperkalemia from stored blood AND hypocalcemia from citrate (used as anticoagulant in blood bags, chelating ionized calcium)", "Metabolic alkalosis and hypernatremia", "Hypermagnesemia", "Polycythemia from excess RBCs"]', 0, 'Stored RBCs leak K+ over time (high K+ in stored blood → hyperkalemia). Citrate anticoagulant in blood products chelates ionized calcium → hypocalcemia (manifests as tetany, prolonged QT, cardiac dysfunction). Treatment: calcium chloride or gluconate infusion during massive transfusion protocols.'),
    (v_topic_id, 'Transfusion-associated graft-versus-host disease (TA-GvHD) is rare but highly fatal. Who is at greatest risk?', '["All transfusion recipients", "Severely immunocompromised patients (e.g., post-BMT, SCID, congenital immunodeficiency) and recipients of HLA-matched (family member donor) blood — donor T-cells engraft and attack recipient tissues", "Patients with autoimmune diseases", "Elderly patients on aspirin"]', 1, 'TA-GvHD: viable donor T-lymphocytes in blood product engraft and attack recipient tissues (skin, GI tract, liver, marrow). Fatal in >90% (marrow aplasia from donor T-cells attacking recipient marrow). Prevention: irradiation of blood products (inactivates donor lymphocytes) for high-risk patients. Leukoreduction alone is insufficient.'),

    -- SPLEEN DISORDERS (296-300)
    (v_topic_id, 'Hypersplenism causes cytopenias by which mechanism?', '["Spleen destroys hematopoietic stem cells", "Enlarged spleen sequesters and destroys excessive numbers of blood cells (RBCs, WBCs, platelets) — all cell lines can be reduced (pancytopenia) with a hypercellular compensatory bone marrow", "Spleen produces inhibitors of bone marrow", "Spleen traps coagulation factors"]', 1, 'Hypersplenism: ANY cause of splenomegaly can cause increased cellular sequestration and destruction. Characteristic: pancytopenia (all three lines reduced) + hypercellular bone marrow (compensating) + splenomegaly. Common causes: portal hypertension (liver disease), storage diseases, hemolytic anemias, infiltrative diseases (lymphoma).'),
    (v_topic_id, 'Asplenic patients (post-splenectomy or functional asplenia in sickle cell disease) are at greatest risk for overwhelming infections with which organisms?', '["Intracellular organisms: Listeria and Mycobacteria", "Encapsulated bacteria: Streptococcus pneumoniae (most common), Haemophilus influenzae type b, Neisseria meningitidis", "Gram-negative rods: E. coli and Klebsiella", "Fungi: Aspergillus and Candida"]', 1, 'The spleen filters encapsulated bacteria (which resist opsonization without specific antibodies) via marginal zone B-cells and macrophages. Post-splenectomy, opsonization of encapsulated organisms is severely impaired. S. pneumoniae causes OPSI (overwhelming post-splenectomy infection) most commonly — can be fatal within hours.'),
    (v_topic_id, 'Howell-Jolly bodies on peripheral blood smear indicate which condition?', '["Iron deficiency anemia", "Asplenia (surgical or functional) — the spleen normally removes DNA remnants (Howell-Jolly bodies = nuclear fragments) from circulating RBCs; without a functioning spleen, these persist", "Megaloblastic anemia", "Hemolytic anemia"]', 1, 'Howell-Jolly bodies = small dark nuclear remnants in RBCs, normally removed by the spleen by a process called pitting. Their presence on smear is a reliable marker of asplenia or hyposplenism. Also seen post-splenectomy: target cells, acanthocytes, nucleated RBCs, and thrombocytosis (initially).'),
    (v_topic_id, 'Gaucher Disease is the most common lysosomal storage disease and classically causes splenomegaly. What accumulates in macrophages?', '["Sphingomyelin in Niemann-Pick disease", "Glucocerebrosides (glucosylceramide) — due to beta-glucocerebrosidase (glucocerebrosidase) deficiency, causing accumulation of substrate in macrophages/monocytes throughout the body", "GM2 ganglioside (Tay-Sachs disease)", "Glycogen (Pompe disease)"]', 1, 'Gaucher disease (autosomal recessive): glucocerebrosidase deficiency → glucocerebroside accumulates in macrophages. Classic Gaucher cells: macrophages with wrinkled tissue-paper cytoplasm. Organs: massive splenomegaly + hepatomegaly + bone involvement (Erlenmeyer flask deformity, bone crises, AVN). No CNS involvement in Type 1 (most common). Treatment: enzyme replacement therapy (imiglucerase).'),
    (v_topic_id, 'A patient has massive splenomegaly, pancytopenia, and bone marrow biopsy shows macrophages with wrinkled tissue-paper cytoplasm that stain PAS-positive. What enzyme assay confirms the diagnosis?', '["Hexosaminidase A (Tay-Sachs)", "Glucocerebrosidase (beta-glucosidase) activity assay in leukocytes or dried blood spot — low activity confirms Gaucher disease", "Sphingomyelinase (Niemann-Pick)", "Alpha-L-iduronidase (Hurler syndrome)"]', 1, 'Gaucher diagnosis: enzyme assay (glucocerebrosidase activity in leukocytes or dried blood spot) + GBA gene mutation analysis. Bone marrow biopsy shows classic Gaucher cells (wrinkled tissue paper cytoplasm). Acid phosphatase is elevated (tartrate-resistant, unlike hairy cell leukemia which is TRAP+). Chitotriosidase is markedly elevated as a biomarker.')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
